    int g = idx / nb, i = idx % nb;
    int ci = p + i;
    const float* Vi = Ps + (size_t)i * n;
    const float* Cg = Cs + (size_t)g * n;
    float a0 = Cg[ci];  // V[ci,i]=1 term
    float a1 = 0.f, a2 = 0.f, a3 = 0.f;
