    for (; r + 3 < n; r += 4) {
        a0 += Vi[r]     * Cg[r];
        a1 += Vi[r + 1] * Cg[r + 1];
        a2 += Vi[r + 2] * Cg[r + 2];
        a3 += Vi[r + 3] * Cg[r + 3];
    }
    for (; r < n; ++r) a0 += Vi[r] * Cg[r];
    Ws[(size_t)i + (size_t)g * NB] = (a0 + a1) + (a2 + a3);
}
