    int gt = idx / nr2;
    int rp = idx % nr2;
    int ra = p + rp * 2;
    int rb = ra + 1;
    bool hb = (rb < n);
    int g0c = gt * 4;
    bool h1 = (g0c + 1 < ct), h2 = (g0c + 2 < ct), h3 = (g0c + 3 < ct);
    float a0 = 0, a1 = 0, a2 = 0, a3 = 0;  // row ra
    float b0 = 0, b1 = 0, b2 = 0, b3 = 0;  // row rb
    for (int i = 0; i < nb; ++i) {
        int ci = p + i;
        if (ra < ci && (!hb || rb < ci)) break;
        const float* Wpi = Wp + i;
        float w0 = Wpi[(size_t)(g0c) * NB];
        float w1 = h1 ? Wpi[(size_t)(g0c + 1) * NB] : 0.f;
        float w2 = h2 ? Wpi[(size_t)(g0c + 2) * NB] : 0.f;
        float w3 = h3 ? Wpi[(size_t)(g0c + 3) * NB] : 0.f;
