// Cs[r,g] -= sum_i V[r,i] * W'[i,g]   (r>=p).  Register-tile a
// 2-row x 4-col block per thread: load the 4 W'[i,g] values once
// per i and reuse across both rows; the two Ps[i*n+r] reads are
// adjacent rows (coalesced). This is the bulk trailing GEMM.
const float* Wp = Ws + (size_t)NB * CT;
int nrows = n - p;          // active rows r in [p, n)
int nr2 = (nrows + 1) / 2;  // row-pairs
int ng4 = (ct + 3) / 4;     // g-tiles of width 4
for (int idx = tid; idx < nr2 * ng4; idx += TPB) {
    int gt = idx / nr2;
    int rp = idx % nr2;
    int ra = p + rp * 2;
    int rb = ra + 1;
    bool hb = (rb < n);
    int g0c = gt * 4;
    bool h1 = (g0c + 1 < ct), h2 = (g0c + 2 < ct), h3 = (g0c + 3 < ct);
    float a0 = 0, a1 = 0, a2 = 0, a3 = 0;  // row ra
    float b0 = 0, b1 = 0, b2 = 0, b3 = 0;  // row rb
    for (int i = 0; i < nb; ++i) {
        int ci = p + i;
        if (ra < ci && (!hb || rb < ci)) break;
        const float* Wpi = Wp + i;
        float w0 = Wpi[(size_t)(g0c) * NB];
        float w1 = h1 ? Wpi[(size_t)(g0c + 1) * NB] : 0.f;
        float w2 = h2 ? Wpi[(size_t)(g0c + 2) * NB] : 0.f;
        float w3 = h3 ? Wpi[(size_t)(g0c + 3) * NB] : 0.f;
        const float* Pi = Ps + (size_t)i * n;
        if (ra >= ci) {
            float va = (ra == ci) ? 1.f : Pi[ra];
            a0 += va * w0; a1 += va * w1; a2 += va * w2; a3 += va * w3;
        }
        if (hb && rb >= ci) {
            float vb = (rb == ci) ? 1.f : Pi[rb];
            b0 += vb * w0; b1 += vb * w1; b2 += vb * w2; b3 += vb * w3;
        }
    }
    Cs[(size_t)(g0c) * n + ra] -= a0;
    if (h1) Cs[(size_t)(g0c + 1) * n + ra] -= a1;
    if (h2) Cs[(size_t)(g0c + 2) * n + ra] -= a2;
    if (h3) Cs[(size_t)(g0c + 3) * n + ra] -= a3;
    if (hb) {
        Cs[(size_t)(g0c) * n + rb] -= b0;
        if (h1) Cs[(size_t)(g0c + 1) * n + rb] -= b1;
        if (h2) Cs[(size_t)(g0c + 2) * n + rb] -= b2;
        if (h3) Cs[(size_t)(g0c + 3) * n + rb] -= b3;
    }
